const sections=[['classification','Abelian Group Classification','◈','Classify finite abelian groups and explore the order-72 example.'],['builder','Group Builder','⊞','Build cyclic and direct-product groups with Cayley tables.'],['calculator','Calculator','＋','A standard arithmetic calculator.'],['permutation','Permutation Lab','↔','Compose permutations; find cycles, inverse, order and parity.'],['dihedral','Dihedral Group Lab','⬡','Explore rotations, reflections and element orders.'],['exercises','Exercises','✎','Guided practice with answers and explanations.'],['notes','Notes & Formulas','▤','Definitions and formulas for quick revision.'],['code','Code Lab','⌘','Algorithms that connect computation to algebra.'],['applications','Real-World Applications','◎','Clock arithmetic, symmetry and transformations.']];
