function layout(content,title){let nav=[['home','⌂','Overview','index.html'],...sections.map(s=>[s[0],s[2],s[1],s[0]+'.html'])];document.getElementById('app').innerHTML='<div class="shell"><aside class="sidebar"><a class="brand" href="index.html"><span class="brand-mark">A</span><span><strong>ALGEBRA STUDIO</strong><small>ABSTRACT ALGEBRA · ARTIFACT 1</small></span></a><div class="nav-label">WORKSPACE</div><nav class="nav">'+nav.map(n=>'<a class="'+(page===n[0]?'active':'')+'" href="'+n[3]+'"><span class="ico">'+n[1]+'</span>'+n[2]+'</a>').join('')+'</nav><div class="side-foot">A focused mathematics workspace.<br>Learn · Explore · Practise</div></aside><main class="main"><header class="topbar"><div class="crumb">Algebra Studio / <b>'+title+'</b></div><span class="top-pill">ARTIFACT 1</span></header><div class="content">'+content+'</div><div class="footer">ALGEBRA STUDIO · ABSTRACT ALGEBRA LEARNING PROJECT</div></main></div>'}
const bookRefs={classification:'Fraleigh, §9.12–9.16: Fundamental Theorem of Finitely Generated Abelian Groups, primary-factor and invariant-factor forms.',builder:'Fraleigh, §9.1–9.4 and §7: direct products, generators and Cayley digraphs.',calculator:'Fraleigh, §6.17: generators of cyclic groups and Euler’s phi function.',permutation:'Fraleigh, §8: groups of permutations, cycle notation, composition, inverses and even/odd permutations.',dihedral:'Fraleigh, §4, Example 7.8 and §11: polygon symmetries, rotations and reflections as permutations/isometries.',exercises:'Practice based on the Artifact 1 guided questions and the matching Fraleigh group-theory sections.',notes:'Revision summary of Fraleigh’s relevant group-theory sections.',code:'Algorithms for the constructions and computations in the relevant Fraleigh sections.',applications:'Illustrations of cyclic groups, permutations and polygon symmetries.'};
function head(t,d){return '<div class="page-head"><div class="eyebrow">ABSTRACT ALGEBRA</div><h1>'+t+'</h1><p>'+d+'</p><p class="muted"><b>Textbook alignment:</b> '+(bookRefs[page]||'Fraleigh, A First Course in Abstract Algebra, 8th Edition.')+'</p></div>'}
function card(t,b){return '<section class="card"><h2>'+t+'</h2>'+b+'</section>'}
function home(){return '<section class="hero"><div class="eyebrow">YOUR ABSTRACT ALGEBRA WORKSPACE</div><h1>Understand groups.<br>Explore the mathematics.</h1><p>A practical learning studio for finite abelian groups, permutations and dihedral groups. Build examples, test properties and practise key questions.</p><a class="btn light" href="classification.html">Start exploring →</a></section><div class="stats"><div class="stat"><b>09</b><span>Learning sections</span></div><div class="stat"><b>03</b><span>Core algebra topics</span></div><div class="stat"><b>∞</b><span>Examples to explore</span></div></div><div class="section-head"><h2>Explore the workspace</h2><p>Choose a section to open its dedicated dashboard.</p></div><div class="grid">'+sections.map(s=>'<a class="card section-card" href="'+s[0]+'.html"><div class="section-icon">'+s[2]+'</div><h3>'+s[1]+'</h3><p>'+s[3]+'</p><span class="open">OPEN SECTION →</span></a>').join('')+'</div>'}
function classification(){
const tools=[['abelian','◇','Abelian or non-Abelian'],['binary','⊗','Binary operation'],['cayley','▦','Cayley table'],['properties','✓','Group properties'],['hom','⇢','Homomorphism'],['iso','⇄','Isomorphism'],['classify','◈','Finite Abelian classification']];
let tiles=tools.map(t=>'<button class="card section-card tool-tile" onclick="openAbTool(\''+t[0]+'\')"><span class="section-icon">'+t[1]+'</span><h3>'+t[2]+'</h3><p>Open this tool and enter your own question or group data.</p><span class="open">OPEN TOOL →</span></button>').join('');
let fields='<div class="field"><label>SET ELEMENTS (comma separated)</label><input id="gEls" value="0,1,2"></div><div class="field"><label>OPERATION TABLE (rows separated by ; and entries by ,)</label><textarea id="gTab" rows="3">0,1,2;1,2,0;2,0,1</textarea></div>';
return head('Abelian Group Tools','Select a task. Enter your own finite set, operation table or mapping and get a calculated answer with the reason.')+
'<div class="grid">'+tiles+'</div><div id="abToolWorkspace" class="card" style="display:none;margin-top:18px"><div class="row" style="justify-content:space-between"><h2 id="abToolTitle">Tool</h2><button class="btn ghost small" onclick="closeAbTool()">CLOSE</button></div>'+
'<div id="tool-abelian" class="ab-tool" style="display:none"><h3>Is this group Abelian?</h3><p>Enter the set and its operation table. Example: Z3 under addition modulo 3.</p>'+fields+'<button class="btn" onclick="checkAbelian()">Check now</button><div id="abelianOut" class="result"></div></div>'+
'<div id="tool-binary" class="ab-tool" style="display:none"><h3>Is this a binary operation?</h3><p>Enter a square table. Every pair must have one result inside the set.</p>'+fields+'<button class="btn" onclick="checkBinary()">Check now</button><div id="binaryOut" class="result"></div></div>'+
'<div id="tool-cayley" class="ab-tool" style="display:none"><h3>Generate a Cayley table</h3><div class="field"><label>MODULUS n (1–12)</label><input id="cayN" type="number" value="3" min="1" max="12"></div><div class="field"><label>OPERATION</label><select id="cayOp"><option value="add">Addition modulo n</option><option value="mul">Multiplication modulo n</option></select></div><button class="btn" onclick="makeCayley()">Make table</button><div id="cayOut" class="result"></div></div>'+
'<div id="tool-properties" class="ab-tool" style="display:none"><h3>Find identity, inverses and element orders</h3>'+fields+'<button class="btn" onclick="findGroupProperties()">Find properties</button><div id="propertiesOut" class="result"></div></div>'+
'<div id="tool-hom" class="ab-tool" style="display:none"><h3>Test a homomorphism φ: G → H</h3><p>Provide the elements, operation tables and image of each G element in order.</p><div class="field"><label>G ELEMENTS</label><input id="homA" value="0,1,2"></div><div class="field"><label>G TABLE</label><textarea id="homAT" rows="3">0,1,2;1,2,0;2,0,1</textarea></div><div class="field"><label>H ELEMENTS</label><input id="homB" value="0,1,2"></div><div class="field"><label>H TABLE</label><textarea id="homBT" rows="3">0,1,2;1,2,0;2,0,1</textarea></div><div class="field"><label>MAP IMAGES</label><input id="homMap" value="0,1,2"></div><button class="btn" onclick="checkHom(false)">Check homomorphism</button><div id="homOut" class="result"></div></div>'+
'<div id="tool-iso" class="ab-tool" style="display:none"><h3>Are these groups isomorphic?</h3><p>Enter both operation tables and a proposed bijection.</p><div class="field"><label>G ELEMENTS</label><input id="isoA" value="0,1,2"></div><div class="field"><label>G TABLE</label><textarea id="isoAT" rows="3">0,1,2;1,2,0;2,0,1</textarea></div><div class="field"><label>H ELEMENTS</label><input id="isoB" value="a,b,c"></div><div class="field"><label>H TABLE</label><textarea id="isoBT" rows="3">a,b,c;b,c,a;c,a,b</textarea></div><div class="field"><label>MAP IMAGES</label><input id="isoMap" value="a,b,c"></div><button class="btn" onclick="checkHom(true)">Check isomorphism</button><div id="isoOut" class="result"></div></div>'+
'<div id="tool-classify" class="ab-tool" style="display:none"><h3>Classify finite Abelian groups</h3><p>Enter the order of the group.</p><div class="field"><label>GROUP ORDER (1–500)</label><input id="classN" type="number" value="72" min="1" max="500"></div><button class="btn" onclick="classify()">Find all possible groups</button><div id="classOut" class="result"></div></div></div>';
}
function openAbTool(id){document.getElementById('abToolWorkspace').style.display='block';document.querySelectorAll('.ab-tool').forEach(x=>x.style.display='none');document.getElementById('tool-'+id).style.display='block';let names={abelian:'Abelian or non-Abelian?',binary:'Binary operation checker',cayley:'Cayley table generator',properties:'Group properties',hom:'Homomorphism checker',iso:'Isomorphism checker',classify:'Finite Abelian group classifier'};document.getElementById('abToolTitle').textContent=names[id];document.getElementById('abToolWorkspace').scrollIntoView({behavior:'smooth'});if(id==='classify')classify()}
function closeAbTool(){document.getElementById('abToolWorkspace').style.display='none'}
function readFiniteTable(et,tt){let els=et.split(',').map(x=>x.trim()),rows=tt.trim().split(';').map(x=>x.split(',').map(y=>y.trim()));if(!els.length||els.some(x=>!x)||new Set(els).size!==els.length)throw Error('Enter distinct elements separated by commas.');if(rows.length!==els.length||rows.some(x=>x.length!==els.length))throw Error('Table must be square: '+els.length+' rows and '+els.length+' columns.');let idx=new Map(els.map((x,i)=>[x,i]));if(rows.flat().some(x=>!idx.has(x)))throw Error('Every table result must be an element of your set.');return {els,rows,idx,n:els.length,op:(i,j)=>idx.get(rows[i][j])}}
function inspectGroup(g){let assoc=true,ids=[],inv={};for(let i=0;i<g.n;i++)for(let j=0;j<g.n;j++)for(let k=0;k<g.n;k++)if(g.op(g.op(i,j),k)!==g.op(i,g.op(j,k)))assoc=false;for(let e=0;e<g.n;e++)if(g.els.every((x,i)=>g.op(e,i)===i&&g.op(i,e)===i))ids.push(e);let e=ids[0];if(e!==undefined)for(let i=0;i<g.n;i++)inv[i]=g.els.map((x,j)=>j).filter(j=>g.op(i,j)===e&&g.op(j,i)===e);let inverses=e!==undefined&&Object.values(inv).every(x=>x.length>0);return {assoc,ids,inv,inverses,isGroup:assoc&&ids.length===1&&inverses}}
function checkAbelian(){let o=document.getElementById('abelianOut');try{let g=readFiniteTable(document.getElementById('gEls').value,document.getElementById('gTab').value),q=inspectGroup(g),bad=[];for(let i=0;i<g.n;i++)for(let j=i+1;j<g.n;j++)if(g.op(i,j)!==g.op(j,i))bad.push({a:g.els[i],b:g.els[j],ab:g.els[g.op(i,j)],ba:g.els[g.op(j,i)]});let line=(name,ok,detail)=>'<li><b>'+(ok?'✓ ':'✗ ')+name+'</b> — '+detail+'</li>';if(!q.isGroup){let checks=line('Closure','true','Every table answer is in the set.')+line('Associativity',q.assoc,q.assoc?'The grouping of three elements does not change the answer.':'Some three elements give different answers when grouped differently.')+line('Identity',q.ids.length===1,q.ids.length===0?'No element leaves every element unchanged.':q.ids.length===1?'One identity exists.':'More than one identity was found; check the table.')+line('Inverses',q.inverses,q.inverses?'Every element has an inverse.':'At least one element has no inverse.');o.innerHTML='<b> This is NOT a group, so it cannot be called Abelian or non-Abelian.</b><p>First, a structure must satisfy all group rules:</p><ul>'+checks+'</ul>';return}if(bad.length){let x=bad[0];o.innerHTML='<b> This is a NON-ABELIAN GROUP.</b><p>It satisfies all group rules, but the operation is not commutative.</p><p><b>Here is a counterexample:</b></p><div class="formula">'+x.a+' ⋆ '+x.b+' = '+x.ab+'<br>'+x.b+' ⋆ '+x.a+' = '+x.ba+'</div><p>Because '+x.ab+' ≠ '+x.ba+', the order changes the answer. Therefore, the group is non-Abelian.</p>';return}o.innerHTML='<b> This is an ABELIAN GROUP.</b><p>All group rules are satisfied, and changing the order never changes the answer.</p><div class="formula">a ⋆ b = b ⋆ a &nbsp; for every a,b in G</div><p>Every pair in your table gives the same result in both orders. Therefore, the group is Abelian.</p>'}catch(e){o.textContent=e.message}}
function checkBinary(){let o=document.getElementById('binaryOut');try{let g=readFiniteTable(document.getElementById('gEls').value,document.getElementById('gTab').value);o.innerHTML='<b>YES — valid binary operation.</b><p>Every ordered pair has exactly one result, and every result belongs to the given set. Table size: '+g.n+' × '+g.n+'.</p>'}catch(e){o.innerHTML='<b>Not a valid binary operation table.</b><p>'+e.message+'</p>'}}
function makeCayley(){let n=Number(document.getElementById('cayN').value),op=document.getElementById('cayOp').value,o=document.getElementById('cayOut');if(!Number.isInteger(n)||n<1||n>12){o.textContent='Enter n from 1 to 12.';return}let v=Array.from({length:n},(_,i)=>i),rows=v.map(i=>v.map(j=>op==='add'?(i+j)%n:(i*j)%n));o.innerHTML='<div class="table-wrap"><table><tr><th>⋆</th>'+v.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+rows.map((r,i)=>'<tr><th>'+i+'</th>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</table></div>'}
function findGroupProperties(){let o=document.getElementById('propertiesOut');try{let g=readFiniteTable(document.getElementById('gEls').value,document.getElementById('gTab').value),q=inspectGroup(g);if(!q.isGroup){o.innerHTML='<b>This table is not a group.</b><p>Associativity: '+(q.assoc?'✓':'✗')+'; unique identity: '+(q.ids.length===1?'✓':'✗')+'; all inverses: '+(q.inverses?'✓':'✗')+'.</p>';return}let e=q.ids[0],orders=[];for(let i=0;i<g.n;i++){let x=e,k=0;do{x=g.op(x,i);k++}while(x!==e&&k<=g.n+1);orders.push(g.els[i]+': '+k)}o.innerHTML='<b>Group verified.</b><p>Identity: '+g.els[e]+'</p><p>Inverses: '+g.els.map((x,i)=>x+'⁻¹='+g.els[q.inv[i][0]]).join('; ')+'</p><p>Element orders: '+orders.join('; ')+'</p><p>Group order: '+g.n+'. Each element order divides the group order.</p>'}catch(e){o.textContent=e.message}}
function checkHom(isIso){let p=isIso?'iso':'hom',o=document.getElementById(isIso?'isoOut':'homOut');try{let A=readFiniteTable(document.getElementById(p+'A').value,document.getElementById(p+'AT').value),B=readFiniteTable(document.getElementById(p+'B').value,document.getElementById(p+'BT').value),qa=inspectGroup(A),qb=inspectGroup(B),imgs=document.getElementById(p+'Map').value.split(',').map(x=>x.trim());if(!qa.isGroup||!qb.isGroup)throw Error('Both operation tables must define groups before checking a group homomorphism or isomorphism.');if(imgs.length!==A.n)throw Error('Enter one image for each element of G.');let m=imgs.map(x=>B.idx.get(x));if(m.some(x=>x===undefined))throw Error('Each image must belong to H.');let preserve=true,why=[];for(let i=0;i<A.n;i++)for(let j=0;j<A.n;j++)if(m[A.op(i,j)]!==B.op(m[i],m[j])){preserve=false;if(why.length<3)why.push('Operation fails for '+A.els[i]+' and '+A.els[j]+'.')}let one=new Set(m).size===A.n,onto=new Set(m).size===B.n,ok=preserve&&(!isIso||(one&&onto));o.innerHTML='<b>'+(ok?(isIso?'YES — ISOMORPHISM':'YES — HOMOMORPHISM'):(isIso?'NOT an isomorphism':'NOT a homomorphism'))+'</b><p>Preserves operation: '+(preserve?'✓':'✗')+(isIso?'<br>One-to-one: '+(one?'✓':'✗')+'<br>Onto: '+(onto?'✓':'✗'):'')+'</p>'+why.join('<br>')+(isIso&&preserve&&!one?'<p>It is not one-to-one, so it is not an isomorphism.</p>':'')}catch(e){o.textContent=e.message}}

function parts(n,m=n){if(!n)return[[]];let a=[];for(let i=Math.min(n,m);i>=1;i--)for(let p of parts(n-i,i))a.push([i,...p]);return a}
function factor(n){let a=[];for(let p=2;p*p<=n;p++)if(n%p===0){let e=0;while(n%p===0){n/=p;e++}a.push([p,e])}if(n>1)a.push([n,1]);return a}
function classify(){let n=Number(document.getElementById('classN').value),o=document.getElementById('classOut');if(!Number.isInteger(n)||n<1||n>500){o.textContent='Enter an integer from 1 to 500.';return}let fs=factor(n),groups=[[]];for(let [p,e] of fs){let next=[];for(let g of groups)for(let q of parts(e))next.push([...g,...q.map(k=>p**k)]);groups=next}let rows=groups.map(g=>{let elem=g.slice().sort((a,b)=>a-b),partsByPrime=fs.map(([p])=>elem.filter(x=>{let y=x;while(y%p===0)y/=p;return y===1}).map(x=>{let e=0;while(x%p===0){x/=p;e++}return e}).sort((a,b)=>a-b)),len=Math.max(0,...partsByPrime.map(x=>x.length)),inv=Array.from({length:len},(_,i)=>partsByPrime.reduce((v,arr,j)=>v*Math.pow(fs[j][0],arr[i-(len-arr.length)]||0),1));return {elem,inv}});let fmt=a=>a.length?a.map(x=>'Z<sub>'+x+'</sub>').join(' × '):'Trivial group';o.innerHTML='<b>'+rows.length+' non-isomorphic abelian group(s) of order '+n+'</b><p>Prime factorization: '+(fs.length?fs.map(x=>x[0]+'<sup>'+x[1]+'</sup>').join(' × '):'1')+'</p><div class="table-wrap"><table><tr><th>#</th><th>Elementary-divisor form</th><th>Invariant-factor form</th></tr>'+rows.map((x,i)=>'<tr><td>'+(i+1)+'</td><td>'+fmt(x.elem)+'</td><td>'+fmt(x.inv)+'</td></tr>').join('')+'</table></div><p class="muted">Invariant factors are arranged so each factor divides the next.</p>'}
function gcd(a,b){while(b)[a,b]=[b,a%b];return a}function lcm(a,b){return a/gcd(a,b)*b}
function builder(){return head('Group Builder','Construct cyclic groups and direct products, then inspect the group elements and operation table. The examples use addition modulo each factor.')+card('Build your group','<p>Enter cyclic factor sizes separated by commas. For example, 4 creates Z₄; 2,2 creates Z₂×Z₂; 2,4 creates Z₂×Z₄.</p><div class="field"><label>CYCLIC FACTORS</label><input id="factors" value="2,4"></div><div class="row"><button class="btn" onclick="buildGroup()">Build group</button><button class="btn ghost" onclick="document.getElementById(\'factors\').value=\'2,2\';buildGroup()">Try Z₂ × Z₂</button></div><div id="groupOut" class="result"></div>')+'<div class="grid"><section class="card"><h3>What is Zₙ?</h3><p class="muted">Zₙ={0,1,…,n−1} with addition modulo n. For example, in Z₄, 3+2=5≡1 (mod 4).</p></section><section class="card"><h3>What is a direct product?</h3><p class="muted">In Z₂×Z₄, elements are ordered pairs. Add each coordinate separately and reduce modulo its own factor.</p></section><section class="card"><h3>Group properties</h3><p class="muted">A group needs closure, associativity, an identity and inverses. Component-wise modular addition is also commutative, so these examples are abelian.</p></section></div>'}
function buildGroup(){let ns=document.getElementById('factors').value.split(',').map(x=>Number(x.trim())),o=document.getElementById('groupOut'),size=ns.reduce((a,b)=>a*b,1);if(!ns.length||ns.some(n=>!Number.isInteger(n)||n<1||n>12)||size>120){o.textContent='Use integers from 1 to 12; total group size must not exceed 120.';return}let es=[[]];for(let n of ns){let next=[];for(let e of es)for(let x=0;x<n;x++)next.push([...e,x]);es=next}let f=e=>'('+e.join(',')+')',ord=e=>e.reduce((v,x,i)=>lcm(v,ns[i]/gcd(ns[i],x)),1),html='<b>Group order: '+size+'</b><p>G = '+ns.map(n=>'Z<sub>'+n+'</sub>').join(' × ')+'</p><p>Identity: ( '+ns.map(()=>0).join(', ')+' )</p><p><b>Elements:</b> '+es.map(f).join(', ')+'</p><p><b>Element orders:</b> '+es.map(e=>f(e)+' : '+ord(e)).join(' · ')+'</p><p><b>Inverses:</b> '+es.map(e=>f(e)+' → '+f(e.map((x,i)=>(ns[i]-x)%ns[i]))).join(' · ')+'</p>';if(size<=36)html+='<h3>Cayley table · component-wise addition</h3><div class="table-wrap"><table><tr><th>+</th>'+es.map(e=>'<th>'+f(e)+'</th>').join('')+'</tr>'+es.map(a=>'<tr><th>'+f(a)+'</th>'+es.map(b=>'<td>'+f(a.map((x,i)=>(x+b[i])%ns[i]))+'</td>').join('')+'</tr>').join('')+'</table></div>';else html+='<p class="notice">Cayley table hidden for readability when group order exceeds 36.</p>';html+='<div class="result good">✓ Closure: modular component-wise addition stays in the set.<br>✓ Associativity: inherited from modular addition.<br>✓ Identity and inverses: shown above.<br>✓ The group is abelian.</div>';o.innerHTML=html}
function calculator(){return head('Calculator','A standard arithmetic calculator and a cyclic-group generator finder. This calculator is separate from the Permutation Lab.')+'<div class="two-col">'+card('Standard calculator','<div class="field"><label>FIRST NUMBER</label><input id="ca" type="number" step="any" value="24"></div><div class="field"><label>OPERATION</label><select id="op"><option value="+">Addition (+)</option><option value="-">Subtraction (−)</option><option value="*">Multiplication (×)</option><option value="/">Division (÷)</option><option value="%">Remainder (%)</option><option value="^">Power (aᵇ)</option></select></div><div class="field"><label>SECOND NUMBER</label><input id="cb" type="number" step="any" value="6"></div><button class="btn" onclick="calc()">Calculate</button><div id="calcOut" class="result"></div>')+card('Generator finder for Zₙ','<p>In additive Zₙ, k is a generator exactly when gcd(k,n)=1. The number of generators is Euler’s totient φ(n).</p><div class="field"><label>CYCLIC GROUP ORDER n (1–500)</label><input id="genN" type="number" min="1" max="500" value="6"></div><button class="btn" onclick="findGenerators()">Find generators</button><div id="genOut" class="result"></div><div class="formula">φ(n)=n ∏(1−1/p), over distinct prime divisors p of n.</div>')+'</div><div class="section-head"><h2>Worked example: Z₆</h2><p>gcd(1,6)=1 and gcd(5,6)=1. Its generators are 1 and 5, so φ(6)=2.</p></div><div class="section-head"><h2>Euler totient table: n ≤ 20</h2><p>φ(n) counts the integers from 1 to n that are relatively prime to n.</p></div><div class="table-wrap"><table><tr><th>n</th><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td><td>7</td><td>8</td><td>9</td><td>10</td><td>11</td><td>12</td><td>13</td><td>14</td><td>15</td><td>16</td><td>17</td><td>18</td><td>19</td><td>20</td></tr><tr><th>φ(n)</th><td>1</td><td>1</td><td>2</td><td>2</td><td>4</td><td>2</td><td>6</td><td>4</td><td>6</td><td>4</td><td>10</td><td>4</td><td>12</td><td>6</td><td>8</td><td>8</td><td>16</td><td>6</td><td>18</td><td>8</td></tr></table></div>'}
function calc(){let a=Number(document.getElementById('ca').value),b=Number(document.getElementById('cb').value),op=document.getElementById('op').value,r;if((op==='/'||op==='%')&&b===0){document.getElementById('calcOut').textContent='Cannot divide by zero.';return}r=op==='+'?a+b:op==='-'?a-b:op==='*'?a*b:op==='/'?a/b:op==='%'?a%b:a**b;document.getElementById('calcOut').innerHTML='<b>'+a+' '+op+' '+b+' = '+r+'</b>'}
function findGenerators(){let n=Number(document.getElementById('genN').value),o=document.getElementById('genOut');if(!Number.isInteger(n)||n<1||n>500){o.textContent='Enter an integer from 1 to 500.';return}let gs=Array.from({length:n},(_,k)=>k).filter(k=>gcd(k,n)===1);o.innerHTML='<b>Generators of Z<sub>'+n+'</sub>:</b> '+gs.join(', ')+'<p>Number of generators: <b>φ('+n+') = '+gs.length+'</b></p><p class="muted">Each listed element is relatively prime to n.</p>'}
function permutation(){return head('Permutations','Learn the idea from a familiar situation, watch the movement, then connect it to cycle notation and group theory.')+
'<section class="perm-hero"><div class="perm-kicker">LEARN IT STEP BY STEP</div><h2>One set. Same elements. New positions.</h2><p>Imagine five students changing seats. Nobody disappears and nobody gets a duplicate seat. A permutation is exactly this kind of rearrangement.</p><div class="perm-seat-demo"><div><small>BEFORE</small><div class="perm-seats"><span>A</span><span>B</span><span>C</span><span>D</span><span>E</span></div></div><div class="perm-big-arrow">⇢</div><div><small>AFTER</small><div class="perm-seats perm-after"><span>B</span><span>C</span><span>A</span><span>E</span><span>D</span></div></div></div><div class="perm-hero-note">Every student has exactly one new seat, and every seat is filled.</div></section>'+
'<div class="perm-roadmap"><a href="#perm-meaning">01 · Understand</a><a href="#perm-move">02 · See movement</a><a href="#perm-notation">03 · Read notation</a><a href="#perm-combine">04 · Combine</a><a href="#perm-practice">05 · Try it</a></div>'+
'<section class="perm-lesson" id="perm-meaning"><div class="perm-step-label">01 / THE IDEA</div><h2>What is a permutation?</h2><p>A permutation of a set is a <b>one-to-one and onto function from the set to itself</b>. In simple words, it rearranges the same elements without repeating or losing any element.</p><div class="perm-definition-grid"><div class="perm-definition"><span class="perm-symbol">1 → 2</span><b>One-to-one</b><p>Two different students cannot be sent to the same seat.</p></div><div class="perm-definition"><span class="perm-symbol">All seats filled</span><b>Onto</b><p>Every seat receives a student.</p></div><div class="perm-definition"><span class="perm-symbol">Same set</span><b>From set to itself</b><p>The students and the available seats are the same set.</p></div></div><div class="perm-callout"><b>Remember:</b> A permutation is a rearrangement, not a selection. All elements must appear exactly once.</div></section>'+
'<section class="perm-lesson" id="perm-move"><div class="perm-step-label">02 / WATCH IT HAPPEN</div><h2>Move the elements yourself</h2><p>Use the example below. The top row shows the original positions. The bottom row shows where each element goes. Follow the arrows one at a time.</p><div class="perm-controls"><label for="pa">Choose a permutation (one-line notation)</label><input id="pa" value="2,3,1,5,4" aria-label="Permutation values"><div class="row"><button class="btn" onclick="setPermExample(\'2,3,1,5,4\')">3-cycle + swap</button><button class="btn ghost" onclick="setPermExample(\'2,1,3,4,5\')">One swap</button><button class="btn ghost" onclick="setPermExample(\'1,2,3,4,5\')">Identity</button><button class="btn ghost" onclick="showPermMovement()">Show movement</button></div></div><div id="permVisual" class="perm-stage"><p class="muted">Choose an example or press Show movement.</p></div><div class="perm-explain" id="permStepExplain">A mapping will be explained here.</div></section>'+
'<section class="perm-lesson" id="perm-notation"><div class="perm-step-label">03 / MATHEMATICAL LANGUAGE</div><h2>From arrows to cycle notation</h2><p>In one-line notation, the position tells us the input and the number tells us its image.</p><div class="perm-notation-example"><div><small>ONE-LINE NOTATION</small><strong>(2, 3, 1, 5, 4)</strong><p>σ(1)=2, σ(2)=3, σ(3)=1, σ(4)=5, σ(5)=4</p></div><div class="perm-notation-arrow">⇢</div><div><small>CYCLE NOTATION</small><strong>(1 2 3)(4 5)</strong><p>1 goes to 2, 2 to 3, and 3 returns to 1. Also, 4 and 5 swap.</p></div></div><div class="perm-callout"><b>How to read a cycle:</b> follow the numbers from left to right, then return from the last number to the first. Disjoint cycles do not share elements.</div><div class="perm-mini-grid"><div><b>Identity</b><p>Every element stays fixed: (1)(2)(3), usually written e.</p></div><div><b>Transposition</b><p>A 2-cycle swaps two elements, for example (4 5).</p></div><div><b>Disjoint cycles</b><p>They have no common elements, for example (1 2 3)(4 5).</p></div></div><div class="row"><button class="btn" onclick="analysePerm()">Analyse my permutation</button></div><div id="permOut" class="result">Your cycle notation, inverse, order and parity will appear here.</div></section>'+
'<section class="perm-lesson" id="perm-combine"><div class="perm-step-label">04 / GROUP OPERATION</div><h2>What happens when we combine permutations?</h2><p>Permutations can be composed. The important rule is: <b>work from right to left</b>.</p><div class="perm-composition-rule"> (σ ∘ τ)(i) = σ(τ(i)) <span>Apply τ first, then apply σ.</span></div><div class="perm-controls"><label for="pb">Second permutation τ (same number of elements)</label><input id="pb" value="2,1,3,4,5"><div class="row"><button class="btn" onclick="composeLesson()">Show σ ∘ τ</button></div></div><div id="composeOut" class="result">The combined mapping will appear here.</div><div class="perm-mini-grid"><div><b>Inverse</b><p>Undo the movement. If σ sends 1 to 2, then σ⁻¹ sends 2 back to 1.</p></div><div><b>Order</b><p>The smallest positive number of times a permutation must be repeated to return to the identity. Find it using the LCM of disjoint cycle lengths.</p></div><div><b>Parity</b><p>Every permutation is even or odd. A transposition is odd; a 3-cycle is even.</p></div></div></section>'+
'<section class="perm-lesson" id="perm-practice"><div class="perm-step-label">05 / YOUR TURN</div><h2>Check your understanding</h2><p>For σ = (1 2 3)(4 5), answer these quick questions.</p><div class="perm-question"><b>1. What is σ(1)?</b><div class="row"><button class="btn ghost" onclick="permQuiz(1,2)">2</button><button class="btn ghost" onclick="permQuiz(1,3)">3</button><button class="btn ghost" onclick="permQuiz(1,1)">1</button></div><div id="pq1" class="perm-feedback"></div></div><div class="perm-question"><b>2. What is the order of σ?</b><div class="row"><button class="btn ghost" onclick="permQuiz(2,3)">3</button><button class="btn ghost" onclick="permQuiz(2,5)">5</button><button class="btn ghost" onclick="permQuiz(2,6)">6</button></div><div id="pq2" class="perm-feedback"></div></div><div class="perm-question"><b>3. Is σ even or odd?</b><div class="row"><button class="btn ghost" onclick="permQuiz(3,\'even\')">Even</button><button class="btn ghost" onclick="permQuiz(3,\'odd\')">Odd</button></div><div id="pq3" class="perm-feedback"></div></div></section>'+
'<section class="perm-summary"><div class="perm-step-label">THE BIG PICTURE</div><h2>Groups of permutations</h2><p>All permutations of {1,…,n} form the <b>symmetric group Sₙ</b> under composition. It has n! elements. The even permutations form the <b>alternating group Aₙ</b>, which has n!/2 elements for n ≥ 2.</p><div class="perm-group-facts"><div><strong>|S₅| = 120</strong><span>All permutations</span></div><div><strong>|A₅| = 60</strong><span>Even permutations</span></div><div><strong>60</strong><span>Odd permutations in S₅</span></div></div><p class="muted">A₅ is a subgroup of S₅. Odd permutations are not a subgroup.</p></section>';}
let permVisualIndex=0;
function setPermExample(v){document.getElementById('pa').value=v;showPermMovement()}
function showPermMovement(){drawPermVisual(0)}
function drawPermVisual(index){const out=document.getElementById('permVisual');if(!out)return;try{const a=readPerm('pa');permVisualIndex=Math.max(0,Math.min(index,a.length-1));const top=a.map((v,i)=>'<div class="perm-tile '+(i===permVisualIndex?'active':'')+'"><span class="perm-tile-num">'+(i+1)+'</span><span class="perm-tile-arrow">↓</span><span class="perm-tile-num target">'+v+'</span><small>'+(i+1)+' goes to '+v+'</small></div>').join('');const i=permVisualIndex,v=a[i];out.innerHTML='<div class="perm-map-labels"><span>STARTING ELEMENT</span><span>ITS IMAGE</span></div><div class="perm-tile-row">'+top+'</div><div class="perm-step-buttons"><button class="btn ghost" onclick="movePermVisual(-1)" '+(i===0?'disabled':'')+'>← Previous</button><span>Step '+(i+1)+' / '+a.length+'</span><button class="btn" onclick="movePermVisual(1)" '+(i===a.length-1?'disabled':'')+'>Next →</button></div><div class="perm-progress"><span style="width:'+((i+1)/a.length*100)+'%"></span></div>';document.getElementById('permStepExplain').innerHTML='<b>Step '+(i+1)+':</b> σ('+(i+1)+') = '+v+'. '+(v===i+1?'Element '+(i+1)+' stays in its original position (a fixed point).':'Element '+(i+1)+' moves to position '+v+'.')+'<br><span class="muted">When every arrow is followed, the complete rearrangement is the permutation.</span>';}catch(e){out.innerHTML='<p class="perm-error">'+e.message+'</p>';document.getElementById('permStepExplain').textContent='Check the input and try again.';}}
function movePermVisual(delta){drawPermVisual(permVisualIndex+delta)}
function permQuiz(q,v){const answers={1:2,2:6,3:'odd'},why={1:'The cycle (1 2 3) sends 1 to 2.',2:'The cycle lengths are 3 and 2, so the order is lcm(3,2)=6.',3:'A 3-cycle is even (two transpositions), while (4 5) is odd. Their product is odd.'};const out=document.getElementById('pq'+q);if(!out)return;const ok=v===answers[q];out.innerHTML='<b class="'+(ok?'perm-correct':'perm-incorrect')+'">'+(ok?'Correct!':'Not quite.')+'</b> '+why[q];}
function composeLesson(){let o=document.getElementById('composeOut');try{let a=readPerm('pa'),b=readPerm('pb');if(a.length!==b.length)throw Error('Both permutations must have the same number of elements.');let c=b.map(x=>a[x-1]);o.innerHTML='<b>First apply τ, then σ:</b><div class="formula">τ = ('+b.join(' ')+')<br>σ = ('+a.join(' ')+')<br>σ ∘ τ = ('+c.join(' ')+')</div><p>For example, 1 → '+b[0]+' under τ, then '+b[0]+' → '+a[b[0]-1]+' under σ. So (σ ∘ τ)(1) = '+c[0]+'.</p><p><b>Cycle notation:</b> '+cyc(c)+'</p>';}catch(e){o.textContent=e.message}}

let permVisualIndex=0;
function drawPermVisual(index){const out=document.getElementById('permVisual');if(!out)return;try{const a=readPerm('pa');permVisualIndex=Math.max(0,Math.min(index,a.length-1));const rows=a.map((v,i)=>'<div class="perm-map '+(i===permVisualIndex?'chosen':'')+'"><span class="perm-node">'+(i+1)+'</span><span class="perm-arrow">→</span><span class="perm-node">'+v+'</span><span class="perm-caption">'+(i+1)+' maps to '+v+'</span></div>').join('');const i=permVisualIndex,v=a[i];out.innerHTML='<div class="perm-map-grid">'+rows+'</div><div class="result good"><b>Step '+(i+1)+' of '+a.length+':</b> σ('+(i+1)+') = '+v+'. '+(v===i+1?'This element stays fixed.':'Element '+(i+1)+' moves to position '+v+'.')+'</div><p class="muted">One-line notation: ('+a.join(' ')+') · Cycle notation: '+cyc(a)+'</p>';}catch(e){out.innerHTML='<p class="err">'+e.message+'</p>';}}
function movePermVisual(delta){drawPermVisual(permVisualIndex+delta);}
function buildSn(){let n=Number(document.getElementById('snBuildN').value),o=document.getElementById('snBuildOut');if(!Number.isInteger(n)||n<2||n>5){o.textContent='Choose n from 2 to 5.';return}let all=[];function permute(a,left){if(!left.length){all.push(a);return}for(let i=0;i<left.length;i++)permute([...a,left[i]],[...left.slice(0,i),...left.slice(i+1)])}permute([],Array.from({length:n},(_,i)=>i+1));let even=all.filter(a=>par(a).even),odd=all.filter(a=>!par(a).even),fmt=a=>a.map(x=>'['+x.join(', ')+']').join(', ');o.innerHTML='<b>|S<sub>'+n+'</sub>| = '+n+'! = '+all.length+'</b><p>Even permutations |A<sub>'+n+'</sub>| = <b>'+even.length+'</b> = n!/2</p><p>Odd permutations = <b>'+odd.length+'</b></p><details><summary>Show all '+even.length+' even permutations (A<sub>'+n+'</sub>)</summary><p>'+fmt(even)+'</p></details><details><summary>Show all '+odd.length+' odd permutations</summary><p>'+fmt(odd)+'</p></details><p class="muted">Each entry is shown in one-line notation. The split is determined by the parity of the inversion count.</p>';}
function snCounts(){let n=Number(document.getElementById('snN').value),o=document.getElementById('snOut');if(!Number.isInteger(n)||n<2||n>10){o.textContent='Enter n from 2 to 10.';return}let total=1;for(let i=2;i<=n;i++)total*=i;o.innerHTML='|S<sub>'+n+'</sub>| = '+n+'! = <b>'+total+'</b><p>Even permutations: <b>'+total/2+'</b></p><p>Odd permutations: <b>'+total/2+'</b></p><p>|A<sub>'+n+'</sub>| = n!/2 = '+total/2+'</p>';}
function readPerm(id){let a=document.getElementById(id).value.split(',').map(x=>Number(x.trim()));if(!a.length||a.some(x=>!Number.isInteger(x))||new Set(a).size!==a.length||a.some(x=>x<1||x>a.length))throw Error('Enter each integer from 1 to n exactly once.');return a}
function cyc(a){let seen=new Set(),cs=[];for(let i=0;i<a.length;i++){if(seen.has(i)||a[i]===i+1)continue;let c=[],j=i;while(!seen.has(j)){seen.add(j);c.push(j+1);j=a[j]-1}cs.push('('+c.join(' ')+')')}return cs.join(' ')||'e (identity)'}
function po(a){let seen=new Set(),v=1;for(let i=0;i<a.length;i++)if(!seen.has(i)){let j=i,k=0;while(!seen.has(j)){seen.add(j);j=a[j]-1;k++}if(k)v=lcm(v,k)}return v}
function cycleArrays(a){let seen=new Set(),cs=[];for(let i=0;i<a.length;i++){if(seen.has(i))continue;let c=[],j=i;while(!seen.has(j)){seen.add(j);c.push(j+1);j=a[j]-1}if(c.length>1)cs.push(c)}return cs}
function permMappingTable(a,inv){return '<div class="table-wrap"><table><tr><th>x</th>'+a.map((_,i)=>'<td>'+(i+1)+'</td>').join('')+'</tr><tr><th>σ(x)</th>'+a.map(x=>'<td>'+x+'</td>').join('')+'</tr><tr><th>σ⁻¹(x)</th>'+inv.map(x=>'<td>'+x+'</td>').join('')+'</tr></table></div>'}
function permutationSubgroupTable(){let o=document.getElementById('permTableOut');try{let a=readPerm('pa'),id=a.map((_,i)=>i+1),powers=[id],composeP=(x,y)=>y.map(v=>x[v-1]);while(true){let next=composeP(powers[powers.length-1],a);if(next.every((v,i)=>v===i+1))break;powers.push(next);if(powers.length>a.length*2)throw Error('Could not generate cyclic subgroup.')}let fmt=x=>'('+x.join(' ')+')',cells=powers.map(x=>powers.map(y=>fmt(composeP(x,y))));o.innerHTML='<b>⟨σ⟩ has '+powers.length+' elements</b><p>Generated by repeated composition: '+powers.map(fmt).join(', ')+'</p><div class="table-wrap"><table><tr><th>∘</th>'+powers.map(fmt).map(x=>'<th>'+x+'</th>').join('')+'</tr>'+cells.map((row,i)=>'<tr><th>'+fmt(powers[i])+'</th>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</table></div><p class="muted">Composition is right-to-left. This is the Cayley table of the cyclic subgroup generated by σ.</p>'}catch(e){o.textContent=e.message}}
function par(a){let n=0;for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++)if(a[i]>a[j])n++;return {n,even:n%2===0}}
function analysePerm(){let o=document.getElementById('permOut');try{let a=readPerm('pa'),p=par(a),inv=a.map((_,i)=>a.indexOf(i+1)+1),cycles=cycleArrays(a),trans=cycles.filter(c=>c.length>1).map(c=>c.slice(1).map((_,i)=>'('+c[0]+' '+c[c.length-1-i]+')').join(' '));o.innerHTML='<b>σ = ('+a.join(' ')+')</b><p><b>Disjoint cycle notation:</b> '+cyc(a)+'</p><p><b>Inverse:</b> ('+inv.join(' ')+') = '+cyc(inv)+'</p><p><b>Order:</b> '+po(a)+' (LCM of cycle lengths)</p><p><b>Cycle type:</b> '+cycles.map(c=>c.length).join(', ')+'</p><p><b>Transposition decomposition:</b> '+(trans.join(' ')||'identity')+'</p><p>Inversions: '+p.n+'</p><div class="result '+(p.even?'good':'warn')+'">'+(p.even?'Even permutation; sign = +1.':'Odd permutation; sign = −1.')+'</div><h3>Inverse table</h3>'+permMappingTable(a,inv) }catch(e){o.textContent=e.message}}
function compose(){let o=document.getElementById('permOut');try{let a=readPerm('pa'),b=readPerm('pb');if(a.length!==b.length)throw Error('Both permutations must have the same size.');let c=b.map(x=>a[x-1]),p=par(c);o.innerHTML='<b>σ ∘ τ</b> (apply τ first, then σ)<p>One-line form: ('+c.join(' ')+')</p><p>Cycles: '+cyc(c)+'</p><p>Order: '+po(c)+'</p><p>'+(p.even?'Even permutation.':'Odd permutation.')+'</p>'}catch(e){o.textContent=e.message}}
function dihedral(){return head('Dihedral Group Lab','Dₙ is the symmetry group of a regular n-gon. It contains n rotations and n reflections. Explore element orders and the centre.')+'<div class="two-col">'+card('Explore an element','<div class="field"><label>NUMBER OF SIDES n (3–12)</label><input id="dn" type="number" min="3" max="12" value="6"></div><div class="field"><label>ELEMENT TYPE</label><select id="de"><option value="r0">r⁰ · identity</option><option value="r1">r¹</option><option value="r2">r²</option><option value="s">s · reflection</option><option value="r1s">rs</option><option value="r2s">r²s</option></select></div><button class="btn" onclick="dcalc()">Calculate element</button><div id="dout" class="result"></div>')+card('Defining relations','<div class="formula">rⁿ=e</div><div class="formula">s²=e</div><div class="formula">srs=r⁻¹</div><p>Rotation order: ord(rᵏ)=n/gcd(n,k).</p><p>Every reflection rᵏs has order 2.</p><p>Group order: |Dₙ|=2n.</p>')+'</div>'+card('Compute Dₙ from Zₙ to Zₙ','<p>Work on Zₙ={0,1,…,n−1}. Define the rotation r(x)=x+1 (mod n) and reflection s(x)=−x (mod n). Their compositions give all 2n symmetries as maps from Zₙ to itself.</p><button class="btn" onclick="computeDnMaps()">Compute Dₙ on Zₙ</button><div id="dnMapsOut" class="result"></div>')+'<div class="section-head"><h2>Required practical examples: D₆ and D₈</h2><p>Generate all rotations and reflections with their orders, and identify the centre of each group.</p></div><div class="row"><button class="btn" onclick="dihedralTable(6)">Show D₆</button><button class="btn ghost" onclick="dihedralTable(8)">Show D₈</button></div><div id="dtable" class="result"></div>'+card('Construct Dₙ as permutations of polygon vertices','<p>Let the vertices be 1,…,n. The rotation r sends each vertex to the next one, while the reflection s fixes vertex 1 and reverses the remaining order. Each symmetry is displayed as a permutation in cycle notation. Fraleigh often writes these generators as ρ (rotation) and μ (reflection); this lab uses r and s to match the assignment.</p><button class="btn" onclick="dihedralPermutations()">Build Dₙ as permutations</button><div id="dpermOut" class="result"></div>')+'<div class="formula">Centre: if n is odd, Z(Dₙ)={e}. If n is even, Z(Dₙ)={e,r^(n/2)}.</div>'; }
function computeDnMaps(){let n=Number(document.getElementById('dn').value),o=document.getElementById('dnMapsOut');if(!Number.isInteger(n)||n<3||n>12){o.textContent='Enter n from 3 to 12.';return}let z=Array.from({length:n},(_,x)=>x),maps=[];for(let k=0;k<n;k++){maps.push({name:'r^'+k,kind:'Rotation',values:z.map(x=>(x+k)%n)});maps.push({name:'r^'+k+'s',kind:'Reflection',values:z.map(x=>(k-x+n*2)%n)})}let rows=maps.map(m=>'<tr><td>'+m.name+'</td><td>'+m.kind+'</td><td>'+m.values.join(', ')+'</td></tr>').join('');o.innerHTML='<b>Start with Z<sub>'+n+'</sub> = {'+z.join(', ')+'}</b><p>Rotation: r(x)=x+1 (mod '+n+'). Reflection: s(x)=−x (mod '+n+').</p><p><b>Computed group:</b> D<sub>'+n+'</sub> = {e,r,r²,…,r<sup>'+ (n-1) +'</sup>, s,rs,r²s,…,r<sup>'+(n-1)+'</sup>s}.</p><p><b>Standard form:</b> every element is uniquely r<sup>k</sup>s<sup>j</sup>, where 0≤k<n and j∈{0,1}. Hence |D<sub>'+n+'</sub>|=2n='+2*n+'.</p><div class="table-wrap"><table><tr><th>Standard form</th><th>Map type</th><th>Values f(0), f(1), …, f(n−1)</th></tr>'+rows+'</table></div><p class="muted">Each row is a function Zₙ→Zₙ. The listed values show where every element of Zₙ is sent.</p><div class="formula">rⁿ=e, s²=e, sr=r⁻¹s (equivalently srs=r⁻¹).</div>';}
function dihedralPermutations(){let n=Number(document.getElementById('dn').value),o=document.getElementById('dpermOut');if(!Number.isInteger(n)||n<3||n>12){o.textContent='Enter n from 3 to 12.';return}let rot=k=>Array.from({length:n},(_,i)=>((i+k)%n)+1),ref=k=>Array.from({length:n},(_,i)=>((k-i+n*2)%n)+1),rows=[];for(let k=0;k<n;k++){let a=rot(k),b=ref(k);rows.push('<tr><td>r<sup>'+k+'</sup></td><td>Rotation</td><td>'+a.join(' ')+'</td><td>'+cyc(a)+'</td><td>'+po(a)+'</td></tr>');rows.push('<tr><td>r<sup>'+k+'</sup>s</td><td>Reflection</td><td>'+b.join(' ')+'</td><td>'+cyc(b)+'</td><td>'+po(b)+'</td></tr>')}let identity=Array.from({length:n},(_,i)=>i+1),r=rot(1),s=ref(0),compose=(a,b)=>b.map(x=>a[x-1]),srs=compose(s,compose(r,s)),rinv=rot(n-1),s2=compose(s,s);o.innerHTML='<b>D<sub>'+n+'</sub> as a subgroup of S<sub>'+n+'</sub></b><p>There are '+(2*n)+' distinct vertex permutations: '+n+' rotations and '+n+' reflections.</p><p>r = '+cyc(r)+'; s = '+cyc(s)+'</p><p>Relations checked: r<sup>n</sup>=e ('+(JSON.stringify(rot(n))===JSON.stringify(identity)?'true':'false')+'), s²=e ('+(JSON.stringify(s2)===JSON.stringify(identity)?'true':'false')+'), srs=r<sup>−1</sup> ('+(JSON.stringify(srs)===JSON.stringify(rinv)?'true':'false')+').</p><div class="table-wrap"><table><tr><th>Element</th><th>Type</th><th>One-line permutation</th><th>Disjoint cycles</th><th>Order</th></tr>'+rows.join('')+'</table></div>';}
function dcalc(){let n=Number(document.getElementById('dn').value),v=document.getElementById('de').value,o=document.getElementById('dout');if(!Number.isInteger(n)||n<3||n>12){o.textContent='Enter n from 3 to 12.';return}let k=Number((v.match(/r(\d+)/)||[])[1]||0),ref=v.includes('s');o.innerHTML='<b>|D<sub>'+n+'</sub>| = '+2*n+'</b><p>Element: '+(ref?'r<sup>'+k+'</sup>s':'r<sup>'+k+'</sup>')+'</p><p>Element order: <b>'+(ref?2:n/gcd(n,k))+'</b></p><p>Type: '+(ref?'Reflection':'Rotation')+'</p>'}
function dihedralTable(n){let o=document.getElementById('dtable'),rows=Array.from({length:n},(_,k)=>'<tr><td>r<sup>'+k+'</sup></td><td>Rotation</td><td>'+n/gcd(n,k)+'</td></tr>').join('')+Array.from({length:n},(_,k)=>'<tr><td>r<sup>'+k+'</sup>s</td><td>Reflection</td><td>2</td></tr>').join(''),center=n%2?'{e}':'{e, r<sup>'+(n/2)+'</sup>}';o.innerHTML='<b>D<sub>'+n+'</sub> has order '+(2*n)+'</b><p>Centre Z(D<sub>'+n+'</sub>) = '+center+'</p><div class="table-wrap"><table><tr><th>Element</th><th>Type</th><th>Element order</th></tr>'+rows+'</table></div>'}
const questions=[['Classify all abelian groups of order 72.','There are six: Z₇₂, Z₂×Z₃₆, Z₂×Z₂×Z₁₈, Z₃×Z₂₄, Z₆×Z₁₂, and Z₆×Z₆×Z₂.','72=2³×3². The exponent 3 has 3 partitions and exponent 2 has 2 partitions. Thus 3×2=6 isomorphism types.'],['Find φ(20).','φ(20)=8.','The integers 1,3,7,9,11,13,17,19 are relatively prime to 20.'],['How many even permutations are in S₅?','60.','|S₅|=5!=120. Exactly half are even, so |A₅|=60.'],['Find the order of r² in D₆.','3.','ord(rᵏ)=n/gcd(n,k), so ord(r²)=6/gcd(6,2)=3.'],['Why does Z₂×Z₂ have no element of order 4?','It has no element of order 4.','Every non-identity element has order 2 because doubling either coordinate gives 0 modulo 2.'],['Compare Z₂×Z₂ and Z₄.','They are not isomorphic.','Z₄ has an element of order 4. Every non-identity element of Z₂×Z₂ has order 2. Isomorphic groups must have the same element-order structure.'],['Find an element of order 6 in S₅ and determine its parity.','(1 2 3)(4 5) has order 6 and is odd.','The order is lcm(3,2)=6. A 3-cycle is even, while a transposition is odd; their product is odd.'],['Find the generators of Z₆.','1 and 5; therefore φ(6)=2.','An element k generates Z₆ exactly when gcd(k,6)=1.'],['Find the centre of D₈.','Z(D₈)={e,r⁴}.','For even n, the centre of Dₙ consists of the identity and the half-turn r^(n/2).']];
function exercises(){return head('Guided Exercises','Try each question first, then reveal the answer and its short explanation.')+'<div class="grid">'+questions.map((q,i)=>'<section class="card"><span class="tag">QUESTION '+(i+1)+'</span><h3>'+q[0]+'</h3><button class="btn ghost small" onclick="let x=document.getElementById(\'ans'+i+'\');x.hidden=!x.hidden">Show / hide answer</button><div id="ans'+i+'" class="result" hidden><b>'+q[1]+'</b><p>'+q[2]+'</p></div></section>').join('')+'</div>'}
function notes(){let data=[['Group and subgroup','A group is a set G with a binary operation satisfying closure, associativity, identity and inverses. It is abelian when ab=ba for all a,b∈G.'],['Cyclic groups','A group is cyclic if one element generates every element. In additive Zₙ, ord(k)=n/gcd(n,k). The generators are exactly the k relatively prime to n.'],['Finite abelian classification','Every finite abelian group is a direct product of cyclic prime-power groups. The possible types are determined by integer partitions of the exponents in the prime factorization of |G|.'],['Elementary divisors and invariant factors','Elementary-divisor form uses cyclic factors of prime-power order. Invariant-factor form combines them into Z(d₁)×…×Z(dₖ), where d₁ divides d₂, and so on.'],['Direct products','For G×H, (g₁,h₁)(g₂,h₂)=(g₁g₂,h₁h₂). The identity is (eG,eH), and (g,h)⁻¹=(g⁻¹,h⁻¹).'],['Cayley tables','A Cayley table records the result of applying the group operation to every ordered pair of elements. Each row and column contains every group element exactly once.'],['Permutation notation','A permutation is a bijection of {1,…,n}. Disjoint cycle notation shows the orbits. Composition is right-to-left; the inverse reverses every cycle.'],['Permutation order and parity','The order of a permutation is the LCM of its disjoint cycle lengths. Its sign is (−1)^(n−c), where c counts all disjoint cycles including fixed points; equivalently, sign is (−1)^(inversion count). Even permutations form Aₙ and |Aₙ|=n!/2 for n≥2.'],['Dihedral groups','Dₙ is the symmetry group of a regular n-gon, represented as permutations of its vertices. It has n rotations and n reflections, order 2n, and relations rⁿ=e, s²=e, srs=r⁻¹. Fraleigh also uses ρ for rotation and μ for reflection.'],['Dihedral element orders and centre','ord(rᵏ)=n/gcd(n,k). Every reflection has order 2. The centre is {e} for odd n and {e,r^(n/2)} for even n.'],['Euler totient','φ(n) counts the integers 1≤k≤n with gcd(k,n)=1. If n=∏pᵢ^aᵢ, then φ(n)=n∏(1−1/pᵢ), over distinct primes.']];return head('Notes & Formulas','A compact revision guide: definitions, standard forms and formulas used in the interactive sections.')+'<div class="grid">'+data.map(x=>'<section class="card"><h3>'+x[0]+'</h3><p class="muted" style="font-size:11px;line-height:1.8">'+x[1]+'</p></section>').join('')+'</div>'}
function code(){let d=[['Element order in Zₙ','function orderInZn(k, n) {\n  return n / gcd(n, k);\n}\n// order of 2 in Z6 is 3'],['Permutation order','function permutationOrder(lengths) {\n  return lengths.reduce((a,b) => lcm(a,b), 1);\n}\n// cycle lengths 3 and 2 give order 6'],['Parity by inversions','function isEven(p) {\n  let inversions = 0;\n  for (let i=0; i<p.length; i++)\n    for (let j=i+1; j<p.length; j++)\n      if (p[i] > p[j]) inversions++;\n  return inversions % 2 === 0;\n}']];return head('Code Lab','Short algorithms explain how the mathematics behind the interactive tools can be computed.')+'<div class="grid">'+d.map(x=>'<section class="card"><h3>'+x[0]+'</h3><pre style="white-space:pre-wrap;background:#101827;color:#d9e2ff;padding:14px;border-radius:9px;font-size:10px;line-height:1.7;overflow:auto">'+x[1]+'</pre></section>').join('')+'</div>'}
function applications(){let d=[['Clock arithmetic','A 12-hour clock is arithmetic modulo 12. Starting at 7 and moving forward 9 hours gives 7+9=16≡4 (mod 12). The clock returns to 4 because values wrap around after 12.','Z₁₂ · modular arithmetic'],['Polygon symmetry','A regular polygon can be rotated or reflected without changing its appearance. These symmetries form a group under composition. A square has 4 rotations and 4 reflections, giving 8 symmetries.','Dihedral group D₄'],['Rearranging objects','Permutations describe rearrangements of seats, labels or objects. Composing two arrangements performs one rearrangement after another; the inverse restores the original order.','Symmetric group Sₙ'],['Repeated rotations','If a shape is rotated by a fixed angle again and again, eventually it returns to its starting position. The smallest number of repetitions is the order of that rotation.','Cyclic group'],['Puzzle moves','A legal puzzle move rearranges positions. A sequence of moves is a composition of permutations, and an undo move is the inverse permutation.','Permutation groups'],['Repeating schedules','A repeating weekly or cyclic schedule can be represented by residue classes. After the last position, the count wraps back to the first.','Zₙ'],['Symmetry and transformations','The set of reversible transformations of an object can be studied algebraically: the identity does nothing, composition combines transformations, and every transformation has an inverse.','Group axioms']];return head('Real-World Applications','Group theory is not only symbolic mathematics. It describes repeating systems, symmetry and reversible rearrangements.')+'<div class="grid">'+d.map(x=>'<section class="card"><span class="tag">'+x[2]+'</span><h3>'+x[0]+'</h3><p class="muted" style="font-size:11px;line-height:1.8">'+x[1]+'</p></section>').join('')+'</div>'+card('Try the clock example','<p>Start at 7 o’clock and move forward 9 hours.</p><div class="formula">7 + 9 = 16; 16 mod 12 = 4.</div><p>The result is 4 o’clock. This is exactly addition in Z₁₂.</p>')}
const render={home,classification,builder,calculator,permutation,dihedral,exercises,notes,code,applications};layout((render[page]||home)(),active?active[1]:'Overview');if(page==='builder')buildGroup();